import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 9
    delimiter = "\t"

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=delimiter,
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    try:
        for record in reader:
            records.append(record)
    except csv.Error:
        pass

    def nonempty(record):
        return any(str(value).strip() for value in record)

    def looks_date(value):
        value = value.strip()
        return bool(re.match(r"^\d{1,4}[-/]\d{1,2}[-/]\d{1,4}$", value))

    def looks_time(value):
        value = value.strip()
        return bool(re.match(r"^\d{1,2}:\d{2}(?::\d{2})?$", value))

    def looks_header_field(value):
        value = value.strip()
        return bool(
            value
            and re.match(r"^[A-Za-z_][A-Za-z0-9 _./-]*$", value)
            and not looks_date(value)
            and not looks_time(value)
        )

    def looks_data(record):
        if not record:
            return False
        if looks_date(record[0]):
            return True
        if len(record) > 1 and looks_time(record[1]):
            return True
        return False

    candidates = []
    for index, record in enumerate(records):
        if not nonempty(record):
            continue

        score = 0
        if len(record) == expected_width:
            score += 8
        elif len(record) >= expected_width - 1:
            score += 2

        header_fields = sum(1 for value in record if looks_header_field(value))
        score += min(header_fields, expected_width)

        if record and looks_date(record[0]):
            score -= 8
        if len(record) > 1 and looks_time(record[1]):
            score -= 4

        following = None
        for later in records[index + 1:]:
            if nonempty(later):
                following = later
                break
        if following is not None and looks_data(following):
            score += 10

        if len(record) == expected_width and header_fields >= 3:
            candidates.append((score, index))

    if candidates:
        _, header_index = max(candidates, key=lambda item: (item[0], -item[1]))
    else:
        header_index = next(
            (index for index, record in enumerate(records) if nonempty(record)),
            None,
        )

    if header_index is None:
        return {"columns": [], "rows": []}

    header = list(records[header_index])
    if header:
        header[0] = header[0].lstrip("\ufeff")

    def normalize(record):
        values = list(record)
        if len(values) < expected_width:
            values.extend([""] * (expected_width - len(values)))
        elif len(values) > expected_width:
            values = values[:expected_width - 1] + [
                delimiter.join(values[expected_width - 1:])
            ]
        return values

    columns = normalize(header)
    rows = []

    for record in records[header_index + 1:]:
        if not nonempty(record):
            continue
        rows.append(normalize(record))

    return {"columns": columns, "rows": rows}
